# minimal DNS query and response parse diagnostics
import socket,struct,random
for name in ['commons.local','prices.internal']:
 qid=random.randrange(65536); q=b''.join(bytes([len(x)])+x.encode() for x in name.split('.'))+b'\0'
 pkt=struct.pack('!HHHHHH',qid,0x100,1,0,0,0)+q+struct.pack('!HH',1,1)
 s=socket.socket(socket.AF_INET,socket.SOCK_DGRAM);s.settimeout(2);s.sendto(pkt,('127.0.0.11',53))
 try:
  d,_=s.recvfrom(4096); print(name,'flags',hex(struct.unpack('!H',d[2:4])[0]),'counts',struct.unpack('!HHHH',d[4:12]),'raw',d.hex())
 except Exception as e: print(name,e)
